import{_ as s,C as r,o as a,c as o,a2 as i,b as l,w as t,a as d,E as c,a6 as m}from"./chunks/framework.BFzNpupd.js";const E=JSON.parse('{"title":"⚙️ Telematics Engine & Signal Processing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/signal-processing.md","filePath":"guide/signal-processing.md"}'),p={name:"guide/signal-processing.md"};function h(g,e,u,S,v,_){const n=r("Mermaid");return a(),o("div",null,[e[1]||(e[1]=i('<h1 id="⚙️-telematics-engine-signal-processing" tabindex="-1">⚙️ Telematics Engine &amp; Signal Processing <a class="header-anchor" href="#⚙️-telematics-engine-signal-processing" aria-label="Permalink to &quot;⚙️ Telematics Engine &amp; Signal Processing&quot;">​</a></h1><p>The core telematics pipeline in <code>:speed-core</code> (<code>TelematicsEngine.kt</code>) processes raw GPS fixes through mathematical smoothing and state-machine hysteresis to eliminate false alarms and jitter.</p><hr><h2 id="🔬-mathematical-signal-pipeline" tabindex="-1">🔬 Mathematical Signal Pipeline <a class="header-anchor" href="#🔬-mathematical-signal-pipeline" aria-label="Permalink to &quot;🔬 Mathematical Signal Pipeline&quot;">​</a></h2><p>Raw GPS sensor hardware suffers from multipath reflections, satellite geometry variance, and momentary signal noise. The <code>TelematicsEngine</code> filters raw velocity through three sequential mathematical gates:</p>',5)),(a(),l(m,null,{default:t(()=>[c(n,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BRaw%20GPS%20Fix%3A%20Speed%20%26%20Accuracy%5D%20--%3E%20B%7BAccuracy%20Filter%20%E2%89%A4%2025m%3F%7D%0A%20%20%20%20B%20--%3E%7CNo%20-%20Discard%20Fix%7C%20C%5BEmit%20LowAccuracy%20State%5D%0A%20%20%20%20B%20--%3E%7CYes%20-%20Accept%20Fix%7C%20D%5BExponential%20Moving%20Average%20%CE%B1%20%3D%200.3%5D%0A%20%20%20%20D%20--%3E%20E%5BSmoothed%20Velocity%20Output%5D%0A%20%20%20%20E%20--%3E%20F%7BDual%20Schmitt%20Trigger%20Hysteresis%7D%0A%20%20%20%20F%20--%3E%7CSpeed%20%E2%89%A5%20Limit%20%2B%201.0%20km%2Fh%7C%20G%5BTrigger%20Over-Speed%20Alert%5D%0A%20%20%20%20F%20--%3E%7CSpeed%20%E2%89%A4%20Limit%20-%203.0%20km%2Fh%7C%20H%5BDismiss%20Over-Speed%20Alert%5D%0A%20%20%20%20F%20--%3E%7CWithin%20Corridor%7C%20I%5BMaintain%20Safe%20State%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<hr><h2 id="_1-gps-confidence-accuracy-gating" tabindex="-1">1. GPS Confidence &amp; Accuracy Gating <a class="header-anchor" href="#_1-gps-confidence-accuracy-gating" aria-label="Permalink to &quot;1. GPS Confidence &amp; Accuracy Gating&quot;">​</a></h2><p>Before any velocity reading is processed, <code>TelematicsEngine</code> validates the horizontal accuracy estimate ($2\\sigma$ precision in meters):</p><p>$$\\text{accuracyMeters} \\le 25.0\\text{ m}$$</p><p>If the device reports poor satellite geometry (e.g. inside tunnels or urban canyons where accuracy exceeds $25\\text{ m}$), the fix is discarded and the SDK emits <code>SpeedData.LowAccuracy</code>. This prevents inaccurate velocity spikes from sounding alarms.</p><hr><h2 id="_2-exponential-moving-average-ema-smoothing" tabindex="-1">2. Exponential Moving Average (EMA) Smoothing <a class="header-anchor" href="#_2-exponential-moving-average-ema-smoothing" aria-label="Permalink to &quot;2. Exponential Moving Average (EMA) Smoothing&quot;">​</a></h2><p>To eliminate erratic velocity jitter from raw GPS sensor readings, the engine applies discrete first-order Exponential Moving Average (EMA) smoothing:</p><p>$$v_{\\text{smoothed}}[t] = \\alpha \\cdot v_{\\text{raw}}[t] + (1 - \\alpha) \\cdot v_{\\text{smoothed}}[t-1]$$</p><p>Where:</p><ul><li><strong>$\\alpha = 0.3$</strong> (Alpha coefficient chosen for optimal balance between needle responsiveness and jitter suppression).</li><li>$v_{\\text{raw}}[t]$ is the instantaneous velocity from <code>Location.getSpeed()</code>.</li><li>$v_{\\text{smoothed}}[t-1]$ is the prior smoothed velocity state.</li></ul><hr><h2 id="_3-dual-schmitt-trigger-hysteresis" tabindex="-1">3. Dual Schmitt Trigger Hysteresis <a class="header-anchor" href="#_3-dual-schmitt-trigger-hysteresis" aria-label="Permalink to &quot;3. Dual Schmitt Trigger Hysteresis&quot;">​</a></h2><p>To prevent &quot;fluttering&quot; alarms (where an alarm rapidly toggles on and off when driving right at the limit boundary), the SDK implements asymmetric Schmitt Trigger Hysteresis:</p><p>$$\\text{Alert Trigger Threshold} = v_{\\text{limit}} + 1.0\\text{ km/h} \\quad (+0.278\\text{ m/s})$$</p><p>$$\\text{Alert Dismissal Threshold} = v_{\\text{limit}} - 3.0\\text{ km/h} \\quad (-0.833\\text{ m/s})$$</p><ul><li><strong>Activation:</strong> The over-speed alarm only sounds when smoothed speed crosses $+1.0\\text{ km/h}$ above the legal limit.</li><li><strong>Dismissal:</strong> Once active, the driver must decelerate $-3.0\\text{ km/h}$ below the limit before the alarm turns off.</li></ul><h3 id="minimum-speed-under-speed-stationary-suppression" tabindex="-1">Minimum Speed (Under-Speed) Stationary Suppression <a class="header-anchor" href="#minimum-speed-under-speed-stationary-suppression" aria-label="Permalink to &quot;Minimum Speed (Under-Speed) Stationary Suppression&quot;">​</a></h3><p>To prevent annoying false under-speed alarms when navigating stoplights, traffic, or speed breakers, the SDK employs <strong>Stationary Suppression</strong>. If the vehicle&#39;s speed drops below $8.0\\text{ km/h}$, the under-speed alarm is aggressively suppressed. It will only fire if the vehicle is actively driving ($&gt; 8.0\\text{ km/h}$) but failing to maintain the legal minimum threshold.</p><hr><h2 id="🚀-non-standard-vehicle-advanced-applications" tabindex="-1">🚀 Non-Standard Vehicle &amp; Advanced Applications <a class="header-anchor" href="#🚀-non-standard-vehicle-advanced-applications" aria-label="Permalink to &quot;🚀 Non-Standard Vehicle &amp; Advanced Applications&quot;">​</a></h2><p>Because <code>TelematicsEngine</code> is pure Kotlin and decoupled from Android UI, it can be applied to non-automotive telematics domains:</p><h3 id="_1-consumer-drones-uavs" tabindex="-1">1. Consumer Drones (UAVs) <a class="header-anchor" href="#_1-consumer-drones-uavs" aria-label="Permalink to &quot;1. Consumer Drones (UAVs)&quot;">​</a></h3><ul><li><strong>Use Case:</strong> Regulations cap drone speeds (e.g., $100\\text{ mph}$ in the US).</li><li><strong>Application:</strong> Drone ground control apps running on Android can pipe UAV telemetry directly into <code>TelematicsEngine</code> using <code>SpeedUnit.MILES_PER_HOUR</code> or <code>SpeedUnit.METERS_PER_SECOND</code> to warn pilots if wind currents push the drone past legal airspeed.</li></ul><h3 id="_2-maritime-marine-boats-jet-skis" tabindex="-1">2. Maritime &amp; Marine (Boats &amp; Jet Skis) <a class="header-anchor" href="#_2-maritime-marine-boats-jet-skis" aria-label="Permalink to &quot;2. Maritime &amp; Marine (Boats &amp; Jet Skis)&quot;">​</a></h3><ul><li><strong>Use Case:</strong> Enforcing &quot;No-Wake Zones&quot; ($&lt; 5\\text{ mph}$) near harbors and marinas.</li><li><strong>Application:</strong> Marine chartplotters or boat dashboard tablets ingest GPS velocity using <code>SpeedUnit.MILES_PER_HOUR</code> or <code>SpeedUnit.KILOMETERS_PER_HOUR</code> for auditory No-Wake compliance alarms.</li></ul><h3 id="_3-light-aviation-gliders" tabindex="-1">3. Light Aviation &amp; Gliders <a class="header-anchor" href="#_3-light-aviation-gliders" aria-label="Permalink to &quot;3. Light Aviation &amp; Gliders&quot;">​</a></h3><ul><li><strong>Use Case:</strong> Low-altitude gliders and ultralights monitoring maximum airspeed limits and minimum stall speeds.</li><li><strong>Application:</strong> Flight tracking tablets pipe velocity vectors into <code>TelematicsEngine</code> using <code>SpeedUnit.METERS_PER_SECOND</code> or <code>SpeedUnit.FEET_PER_SECOND</code> to provide visual corridor guidance.</li></ul>',28))])}const A=s(p,[["render",h]]);export{E as __pageData,A as default};
